                              &lt;p&gt;&lt;strong&gt;Media&amp;nbsp;Contact:&lt;/strong&gt;&amp;nbsp;Erica Heartquist, 503-871-8843,&lt;/p&gt;

                              &lt;p&gt;&lt;a href="mailto:PHD.Communications@oha.oregon.gov" rel="noopener" style="color: rgb(6, 66, 118); text-decoration-line: none; text-size-adjust: 100%;" target="_blank"&gt;PHD.Communications@oha.oregon.gov&lt;/a&gt;&amp;nbsp;&lt;/p&gt;
