&lt;div class="abe-section-block" style="margin: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: Verdana, arial, Geneva, Helvetica, Century; font-size: 13.6px; background-color: rgb(221, 221, 221);"&gt;
&lt;table align="center" border="0" cellpadding="0" cellspacing="0" class="abe-section-table" style="border-collapse:collapse; border-spacing:0px; max-width:600px; text-size-adjust:100%; width:100%"&gt;
